import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百九十八章 修建地基","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/198第一百九十八章 修建地基.md","filePath":"meditation/巴利文大藏经/198第一百九十八章 修建地基.md"}'),o={name:"meditation/巴利文大藏经/198第一百九十八章 修建地基.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百九十八章-修建地基",tabindex:"-1"},[l("第一百九十八章 修建地基 "),e("a",{class:"header-anchor",href:"#第一百九十八章-修建地基","aria-label":'Permalink to "第一百九十八章 修建地基"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"20.(9).譬喻相应",-1),e("p",null,"相应部20相应1经/屋顶经(譬喻相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，就如同任何的宫殿楼阁，修建它们之前都要先打好地基，这样才能最终修建好各种宫殿楼阁，如果地基没有打好，再高大的宫殿楼阁都不会稳固，都可能随时坍塌。",-1),e("p",null,"同样的道理，弟子们，任何的不善法、恶法，它们都是由无明生起的，一旦除灭了无明，任何的不善法、恶法就能够根除殆尽。什么是无明呢？就是不明白出生在世间有生命的众生都是很痛苦的，不明白痛苦的根源是贪爱，不明白要灭尽痛苦就要先灭尽贪爱，不明白要灭尽贪爱就要修习八正道（八正道解释，见第十八章），不明白苦集灭道四圣谛，没有真实的智慧，沉迷于各种欲望之中，被各种烦恼和痛苦束缚捆绑不得解脱就叫做「无明」。",-1),e("p",null,"弟子们，你们应该这样去修行：「我们要精进的修习一切善法，断除一切恶法，我们要身体行为做善事，口说善言，内心生起善念，我们要管束好自己的身体行为不做恶事，不说恶言，内心不生起恶念，如此持之以恒的不放逸自己的行为、言语、念想做恶行。如此持之以恒的坚持自己的行为、言语、念想做善行。我们要安住在善法之中，我们要安住在不放逸的清净境界之中。」 弟子们，你们就应该这样的去修行。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
